'use client';
import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import ShiftForm from '../components/ShiftForm';
import ShiftTable from '../components/ShiftTable';
import api from '../utils/api';
import { useRouter } from 'next/navigation';

export default function Dashboard() {
    const { user, loading } = useAuth();
    const [shifts, setShifts] = useState([]);
    const router = useRouter();

    useEffect(() => {
        if (!loading && !user) {
            router.push('/login');
        }
    }, [user, loading, router]);

    const fetchShifts = async () => {
        try {
            const res = await api.get('/shifts');
            setShifts(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (user) {
            fetchShifts();
        }
    }, [user]);

    if (loading || !user) return null;

    return (
        <div className="min-h-screen pb-12">
            <Navbar />
            <div className="max-w-7xl mx-auto px-6">
                <div className="mb-8 flex justify-between items-end">
                    <div>
                        <h1 className="text-3xl font-bold text-white mb-2">
                            {user.role === 'admin' ? 'Admin Dashboard' : 'My Schedule'}
                        </h1>
                        <p className="text-gray-400">
                            {user.role === 'admin'
                                ? 'Manage employee shifts and schedules.'
                                : `View your upcoming shifts, ${user.name}.`}
                        </p>
                    </div>
                    {user.role === 'admin' && (
                        <div className="text-sm text-gray-500">
                            Total Shifts: <span className="text-white font-mono">{shifts.length}</span>
                        </div>
                    )}
                </div>

                {user.role === 'admin' && (
                    <ShiftForm onShiftAdded={fetchShifts} />
                )}

                <ShiftTable shifts={shifts} onDelete={fetchShifts} />
            </div>
        </div>
    );
}
